\begin{lemma}\label{lem:apple}
    For $C$ sufficiently large,
    \begin{equation}
        \frac{\Pr[v_- + X > P_c]}{\Pr[v_+ + X > P_c]} > 1 - \epsilon
    \end{equation}
    for all $c\in \FF_2.$
\end{lemma}

\begin{proposition}\label{prop:beet}
\quad
\begin{itemize}
    \item[(i)] If $v < P_{C^{\phi_3}} - \EE[X^{(C)}] - C^{\phi_4},$
    \begin{equation}
        p_\mu(v, \CC_2) \le O\left(C^{-\beta-2\phi_4}\right).
