\paragraph{Proof of \Cref{prop:lt-large-firms}.} 
We first show a few useful lemmas. The first lemma demonstrates that as $C$ is taken large, almost all college cutoffs are must also be large.

\begin{lemma}\label{lem:unbounded-cutoffs}
    For any $P\in \RR$, $P_{\epsilon C} > P$ for all $C$ sufficiently large.
\end{lemma}

\begin{proof}
    Suppose otherwise. Then there exists $P$ such that there exists $C$ arbitrarily large and $\mu \in M(\DD, C)$ with cutoffs $P_1\le P_2\le \cdots \le P_C$ such that $P_{\epsilon C} \le P$.
    Then we show that the number of applicants who can afford a firm in $\FF_1$ exceeds the total capacity $S$. Indeed,
    \begin{align}
        \int_{-\infty}^\infty p_\mu(v, \CC_1)\,d\eta(v)
        &= \int_{-\infty}^\infty \Pr[v + X_c > P_c\text{ for some $c\in \FF_1$}]\,d\eta(v)\\
        &\ge \int_{-\infty}^\infty \Pr[v + X^{(\epsilon C)} > P_{\epsilon C}]\,d\eta(v)\\
        &\ge \int_{-\infty}^\infty \Pr[v + X^{(\epsilon C)} > P]\,d\eta(v).
    \end{align}
    Since $\DD$ is unbounded from above, the final integral approaches $1$ as $C$ grows large. So for $C$ sufficiently large,
    \begin{equation}
        \int_{-\infty}^\infty p_\mu(v, \CC_1)\,d\eta(v) > S,
    \end{equation}
    which contradicts the fact that the total capacity of colleges is $S$.
\end{proof}

We now use \Cref{lem:unbounded-cutoffs} to show that the probability that applicants with values $v_-$ and $v_+$ have approximately equal chances of affording a college in $\FF_2$ when $C$ is sufficiently large.

\begin{lemma}\label{lem:apple}
    For $C$ sufficiently large,
    \begin{equation}
        \frac{\Pr[v_- + X > P_c]}{\Pr[v_+ + X > P_c]} > 1 - \epsilon
    \end{equation}
    for all $c\in \FF_2.$
\end{lemma}

\begin{proof}
    For $P$ sufficiently large,
    \begin{equation}
        \frac{\Pr[v_- + X > P]}{\Pr[v_+ + X > P]} > 1 - \epsilon
    \end{equation}
    since $\DD$ is long-tailed. By \Cref{lem:unbounded-cutoffs}, for any $P\in \RR$, $P_{\epsilon C} > P$ for all $C$ sufficiently large. Observing that $P_c\ge P_{\epsilon C}$ for all $c\in \FF_2,$ the result follows.
\end{proof}

\Cref{lem:apple} shows that the probability of affording a firm in $\FF_2$ is approximately the same for $v_-$ and $v_+$ We require a slightly stronger result: that the probability of affording \textit{at least one} college in $\FF_2$ is approximately the same. To show this, we also require the following bound.

\begin{lemma}
    There exists a constant $\sigma>0$ such that for $C$ sufficiently large,
    \begin{equation}
        \Pr[v_+ + X > P_c] \le \frac{\sigma}{C}
    \end{equation}
    for all $c\in \FF_2.$
\end{lemma}

\begin{proof}
