\end{proof}

We may now show that the probability $v_-$ and $v_+$ can afford at least one college in $\FF_2$ is approximately the same when $C$ is large.
\begin{proposition}\label{prop:lt-approx-F2}
For $C$ sufficiently large,
\begin{equation}
    p_\mu(v_+, \CC_2) - p_\mu(v_-, \CC_2) < 1 - e^{-2\epsilon\sigma}.
\end{equation}
\end{proposition}
\begin{proof}
We have that
\begin{align}
    p_\mu(v_+, \CC_2) - p_\mu(v_-, \CC_2)
    &= \prod_{c\in \FF_2}\Pr[v_- + X < P_c] - \prod_{c\in \FF_2}\Pr[v_+ + X < P_c]\\
    &= \left(1 - \prod_{c\in \FF_2}\frac{\Pr[v_+ + X < P_c]}{\Pr[v_- + X < P_c]}\right) \prod_{c\in \FF_2}\Pr[v_- + X < P_c]\\
    &< 1 - \prod_{c\in \FF_2}\frac{\Pr[v_+ + X < P_c]}{\Pr[v_- + X < P_c]}
\end{align}
From \Cref{lem:apple},
\begin{equation}
    \Pr[v_- + X > P_c] > (1-\epsilon)\Pr[v_+ + X > P_c]
\end{equation}
for all $c\in \FF_2$. Therefore,
\begin{align}
    \frac{\Pr[v_+ + X < P_c]}{\Pr[v_- + X < P_c]} &= \frac{1 - \Pr[v_+ + X > P_c]}{1 - \Pr[v_- + X > P_c]}\\
    &> \frac{1 - \Pr[v_+ + X > P_c]}{1 - (1-\epsilon)\Pr[v_+ + X > P_c]}.
\end{align}
Continuing,
\begin{align}
    \frac{1 - \Pr[v_+ + X > P_c]}{1 - (1-\epsilon)\Pr[v_+ + X > P_c]} &= 1 - \frac{\epsilon \Pr[v_+ + X > P_c]}{1 - (1-\epsilon) \Pr[v_+ + X > P_c]}\\
    &\ge 1 - \frac{\epsilon\frac{\sigma}{C}}{1 - (1-\epsilon)\frac{\sigma}{C}}\\
    &= 1 - \frac{\epsilon\sigma}{C - (1-\epsilon)\sigma}\\
    &> \exp\left[-\frac{2\epsilon\sigma}{C}\right]
\end{align}
where the last inequality holds when $C$ is sufficiently large. Then we have that
\begin{align}
    1 - \prod_{c\in \FF_2}\frac{\Pr[v_+ + X < P_c]}{\Pr[v_- + X < P_c]}
    &< 1 - \left(\exp\left[-\frac{2\epsilon\sigma}{C}\right]\right)^{|\FF_2|}\\
    &< 1 - e^{-2\epsilon\sigma}.
\end{align}
\end{proof}

\begin{proposition}\label{prop:lt-approx-F2}
For $C$ sufficiently large,
\begin{equation}
    p_\mu(v_+, \CC_2) - p_\mu(v_-, \CC_2) < 1 - e^{-2\epsilon\sigma}.
\end{equation}
\end{proposition}

