        \item[(i)] If $v > P^* - \EE[X^{(C^{\phi_2})}]  + 2\delta,$
        \begin{equation}
            p_\mu(v, \CC_2) \ge 1 - O\left(C^{-2\phi_1 - \beta\phi_2}\right).
